INSERT INTO `products` (`id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `price`, `sale_price`, `stock_quantity`, `thumbnail`, `short_description`, `description`, `specs`, `is_featured`, `is_new`, `status`) VALUES
-- 1. Điện thoại thông minh
(1, 1, 1, 'IP16PM-256', 'iPhone 16 Pro Max 256GB Titan Tự Nhiên', 'iphone-16-pro-max-256gb', 34990000.00, 32490000.00, 25, 'https://images.unsplash.com/photo-1695048133142-1a20484d2569?auto=format&fit=crop&w=800&q=80', 'Flagship cao cấp nhất của Apple với chip A18 Pro và camera nút điều khiển Camera Control.', 'iPhone 16 Pro Max sở hữu màn hình Super Retina XDR 6.9 inch lớn nhất từ trước đến nay với viền mỏng ấn tượng. Khung titan cấp 5 siêu bền nhẹ. Hệ thống camera chuyên nghiệp 48MP Fusion cùng khả năng quay video 4K 120 fps Dolby Vision.', '{"display": "6.9 inch OLED Super Retina XDR 120Hz", "cpu": "Apple A18 Pro 6 nhân", "ram": "8GB", "storage": "256GB NVMe", "camera": "Chính 48MP + Góc rộng 48MP + Tele 5x 12MP", "battery": "4685 mAh, Sạc nhanh 30W MagSafe", "os": "iOS 18"}', 1, 1, 'active'),
(2, 1, 5, 'SAMS24U-512', 'Samsung Galaxy S24 Ultra 5G 512GB Xám Titan', 'samsung-galaxy-s24-ultra-512gb', 33990000.00, 29990000.00, 18, 'https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?auto=format&fit=crop&w=800&q=80', 'Quyền năng Galaxy AI, bút S-Pen tích hợp, khung viền Titanium và camera 200MP Zoom 100x.', 'Samsung Galaxy S24 Ultra trang bị vi xử lý Snapdragon 8 Gen 3 for Galaxy, màn hình phẳng Dynamic AMOLED 2X sáng 2600 nits phủ kính Gorilla Armor chống chói đỉnh cao. Bộ tính năng Galaxy AI thông minh hỗ trợ dịch thuật trực tiếp và khoanh vùng tìm kiếm.', '{"display": "6.8 inch Quad HD+ Dynamic AMOLED 2X 120Hz", "cpu": "Snapdragon 8 Gen 3 for Galaxy (4nm)", "ram": "12GB", "storage": "512GB UFS 4.0", "camera": "200MP + 50MP + 12MP + 10MP", "battery": "5000 mAh, Sạc siêu nhanh 45W", "os": "Android 14, One UI 6.1"}', 1, 0, 'active'),
(3, 1, 1, 'IP15-128', 'iPhone 15 128GB Xanh Mint Chính Hãng VN/A', 'iphone-15-128gb-chinh-hang', 20990000.00, 18990000.00, 40, 'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=800&q=80', 'Thiết kế mặt lưng kính pha màu sang trọng, Dynamic Island tiện lợi và cổng USB-C tiện dụng.', 'iPhone 15 mang đến cụm Dynamic Island trực quan, camera chính 48MP chụp ảnh siêu nét và chip A16 Bionic mạnh mẽ. Cổng kết nối Type-C chuẩn mới thuận tiện khi sạc chung với MacBook và iPad.', '{"display": "6.1 inch Super Retina XDR OLED", "cpu": "Apple A16 Bionic", "ram": "6GB", "storage": "128GB", "camera": "Chính 48MP + Góc siêu rộng 12MP", "battery": "3349 mAh, Hỗ trợ sạc 20W", "os": "iOS 17/18"}', 0, 0, 'active'),

-- 2. Laptop & Máy tính
(4, 2, 1, 'MBP14-M3P', 'MacBook Pro 14 M3 Pro 18GB/512GB Space Black', 'macbook-pro-14-m3-pro-18gb-512gb', 49990000.00, 46490000.00, 12, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80', 'Sức mạnh vượt trội từ chip M3 Pro, màn hình Liquid Retina XDR 120Hz và thời lượng pin 18 giờ.', 'Dành riêng cho lập trình viên, nhà sáng tạo nội dung và kỹ sư đồ họa. Chip Apple M3 Pro với 11 nhân CPU, 14 nhân GPU cùng công nghệ Ray Tracing tăng tốc phần cứng. Hệ thống tản nhiệt chủ động êm ái.', '{"display": "14.2 inch Liquid Retina XDR (3024x1964) ProMotion 120Hz", "cpu": "Apple M3 Pro (11 nhân CPU, 14 nhân GPU)", "ram": "18GB Unified Memory", "storage": "512GB PCIe SSD siêu tốc", "ports": "3x Thunderbolt 4, HDMI, SDXC, MagSafe 3", "weight": "1.61 kg"}', 1, 1, 'active'),
(5, 2, 2, 'ROG-ZEPH-G16', 'ASUS ROG Zephyrus G16 OLED Core Ultra 9 / RTX 4070', 'asus-rog-zephyrus-g16-oled', 61990000.00, 57990000.00, 8, 'https://images.unsplash.com/photo-1603302576837-37561b2e2302?auto=format&fit=crop&w=800&q=80', 'Laptop Gaming mỏng nhẹ cao cấp hàng đầu với màn hình ROG Nebula OLED 2.5K 240Hz.', 'Thiết kế nhôm nguyên khối CNC siêu mỏng chỉ 1.49cm. Cấu hình đỉnh cao Intel Core Ultra 9 185H kết hợp NVIDIA GeForce RTX 4070 8GB GDDR6, hệ thống tản nhiệt buồng hơi tân tiến cho khả năng chiến mọi tựa game AAA.', '{"display": "16 inch 2.5K ROG Nebula OLED 240Hz 0.2ms 100% DCI-P3", "cpu": "Intel Core Ultra 9 185H (16 nhân, 22 luồng up to 5.1GHz)", "gpu": "NVIDIA GeForce RTX 4070 8GB GDDR6 (TGP 105W)", "ram": "32GB LPDDR5X 7467MHz", "storage": "1TB M.2 NVMe PCIe 4.0 SSD", "weight": "1.85 kg"}', 1, 1, 'active'),
(6, 2, 3, 'DELL-XPS13-9340', 'Dell XPS 13 9340 Intel Core Ultra 7 16GB/512GB FHD+', 'dell-xps-13-9340-core-ultra-7', 38990000.00, 36490000.00, 15, 'https://images.unsplash.com/photo-1593642632823-8f785ba67e45?auto=format&fit=crop&w=800&q=80', 'Thiết kế viền vô cực tối giản, thanh cảm ứng điện dung hiện đại và bàn di chuột kính liền mạch.', 'Dòng máy chuẩn mực của phân khúc Ultrabook doanh nhân. Vỏ nhôm gia công CNC kết hợp kính cường lực Gorilla Glass. Vi xử lý Core Ultra 7 tích hợp NPU xử lý trí tuệ nhân tạo chuyên biệt.', '{"display": "13.4 inch FHD+ (1920x1200) InfinityEdge 500 nits 120Hz", "cpu": "Intel Core Ultra 7 155H (16 nhân 22 luồng)", "ram": "16GB LPDDR5x 7467MHz", "storage": "512GB PCIe 4.0 NVMe SSD", "weight": "1.19 kg", "battery": "55Whr"}', 0, 0, 'active'),
(7, 2, 4, 'LEGION-PRO5', 'Lenovo Legion Pro 5 16IRX9 i7-14700HX / RTX 4060', 'lenovo-legion-pro-5-16irx9', 39990000.00, 37490000.00, 14, 'https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?auto=format&fit=crop&w=800&q=80', 'Cỗ máy gaming quốc dân bền bỉ, tản nhiệt Legion ColdFront 5.0 và màn 16 inch 240Hz sắc nét.', 'Lenovo Legion Pro 5 khẳng định vị thế nhờ khung máy đầm chắc, bàn phím Legion TrueStrike gõ cực nảy. CPU Intel Gen 14 dòng HX hiệu năng cao và card RTX 4060 max công suất 140W.', '{"display": "16 inch WQXGA (2560x1600) IPS 240Hz 500nits G-SYNC", "cpu": "Intel Core i7-14700HX (20 nhân, 28 luồng)", "gpu": "NVIDIA GeForce RTX 4060 8GB GDDR6 140W", "ram": "16GB DDR5 5600MHz", "storage": "1TB SSD M.2 2280 PCIe 4.0", "weight": "2.5 kg"}', 0, 0, 'active'),

-- 3. Máy tính bảng
(8, 3, 1, 'IPAD-PRO-11-M4', 'iPad Pro 11 inch M4 Wi-Fi 256GB Đen Không Gian', 'ipad-pro-11-inch-m4-256gb', 28990000.00, 26990000.00, 20, 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=800&q=80', 'Thiết kế mỏng kỷ lục 5.3mm, chip Apple M4 thế hệ mới cùng màn hình Ultra Retina XDR Tandem OLED.', 'Chiếc máy tính bảng đột phá nhất của Apple với công nghệ 2 lớp màn hình OLED xếp chồng cho độ sáng đỉnh 1600 nits. Hỗ trợ Apple Pencil Pro và Magic Keyboard mới.', '{"display": "11 inch Ultra Retina XDR Tandem OLED 120Hz", "cpu": "Apple M4 9 nhân CPU, 10 nhân GPU", "ram": "8GB", "storage": "256GB NVMe", "thickness": "5.3 mm", "weight": "444 g"}', 1, 1, 'active'),
(9, 3, 5, 'TAB-S9-PLUS', 'Samsung Galaxy Tab S9 Plus 5G 12GB/256GB Kèm S-Pen', 'samsung-galaxy-tab-s9-plus-5g', 23990000.00, 20490000.00, 16, 'https://images.unsplash.com/photo-1561154464-82e9adf32764?auto=format&fit=crop&w=800&q=80', 'Màn hình Dynamic AMOLED 2X rực rỡ, chuẩn kháng nước IP68 đầu tiên trên tablet cao cấp.', 'Tablet màn hình lớn 12.4 inch phục vụ tối đa nhu cầu ghi chú, phác thảo đồ họa và đa nhiệm DeX. Trang bị chip Snapdragon 8 Gen 2 for Galaxy và hệ thống 4 loa AKG sống động.', '{"display": "12.4 inch Dynamic AMOLED 2X 120Hz HDR10+", "cpu": "Snapdragon 8 Gen 2 for Galaxy", "ram": "12GB", "storage": "256GB UFS 4.0", "durability": "Chống nước & bụi IP68", "battery": "10090 mAh, Sạc nhanh 45W"}', 0, 0, 'active'),

-- 4. Màn hình máy tính
(10, 4, 3, 'DELL-U2724D', 'Màn hình Dell UltraSharp U2724D 27 inch 2K IPS Black 120Hz', 'dell-ultrasharp-u2724d-27-inch', 11990000.00, 10890000.00, 30, 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=800&q=80', 'Độ chuẩn màu vượt trội 98% DCI-P3, tấm nền IPS Black tương phản 2000:1 và tần số quét mượt mà 120Hz.', 'Màn hình chuẩn mực cho thiết kế đồ họa và sáng tạo. Tích hợp cảm biến ánh sáng xung quanh tự động điều chỉnh độ sáng, chân đế công thái học xoay lật 90 độ linh hoạt.', '{"size": "27 inch", "resolution": "2K QHD (2560 x 1440)", "panel": "IPS Black công nghệ mới", "refresh_rate": "120Hz", "color": "100% sRGB, 98% Display P3, Delta E < 2", "ports": "DisplayPort 1.4, HDMI, USB-C upstream/downstream, Audio out"}', 1, 0, 'active'),
(11, 4, 2, 'ROG-PG27AQDM', 'Màn hình Gaming ASUS ROG Swift OLED PG27AQDM 27 inch 2K 240Hz 0.03ms', 'asus-rog-swift-oled-pg27aqdm', 23990000.00, 21990000.00, 10, 'https://images.unsplash.com/photo-1547082299-de196ea013d6?auto=format&fit=crop&w=800&q=80', 'Tấm nền OLED siêu tốc 240Hz, thời gian phản hồi 0.03ms vô đối cho game thủ Esport.', 'Sự kết hợp hoàn hảo giữa độ tương phản tuyệt đối của OLED và tần số quét khủng 240Hz. Hệ thống tản nhiệt thông minh tùy chỉnh giúp giảm nguy cơ lưu ảnh (burn-in).', '{"size": "26.5 inch OLED", "resolution": "2K QHD (2560 x 1440)", "refresh_rate": "240Hz", "response_time": "0.03ms (GTG)", "brightness": "1000 nits đỉnh (3% APL)", "sync": "G-SYNC Compatible, FreeSync Premium"}', 0, 1, 'active'),

-- 5. Linh kiện máy tính
(12, 5, 8, 'CPU-I7-14700K', 'CPU Intel Core i7 14700K (20 Nhân 28 Luồng / Up to 5.6GHz)', 'intel-core-i7-14700k', 11490000.00, 10490000.00, 45, 'https://images.unsplash.com/photo-1591799264318-7e6ef8ddb7ea?auto=format&fit=crop&w=800&q=80', 'Bộ vi xử lý kiến trúc Raptor Lake Refresh mạnh mẽ cho cả Render đồ họa nặng và Gaming đỉnh cao.', 'Trang bị 8 nhân hiệu năng cao (P-core) và 12 nhân tiết kiệm điện (E-core). Hỗ trợ chuẩn RAM DDR5 và PCIe Gen 5.0, socket LGA1700 tương thích bo mạch chủ Z790/B760.', '{"socket": "LGA 1700", "cores_threads": "20 nhân (8P + 12E), 28 luồng", "clock": "Cơ bản 3.4GHz, Turbo boost 5.6GHz", "cache": "33MB Intel Smart Cache", "tdp": "125W (Tối đa 253W)", "ram_support": "DDR5 5600 / DDR4 3200"}', 1, 0, 'active'),
(13, 5, 12, 'VGA-MSI-4070S-TRIO', 'Card màn hình MSI GeForce RTX 4070 SUPER 12G GAMING X TRIO', 'msi-geforce-rtx-4070-super-12g-gaming-x-trio', 19990000.00, 18490000.00, 12, 'https://images.unsplash.com/photo-1587202372775-e229f172b9d7?auto=format&fit=crop&w=800&q=80', 'Kiến trúc Ada Lovelace, công nghệ nâng khung hình DLSS 3 và tản nhiệt 3 quạt TRI FROZR 3 mát mẻ.', 'Card đồ họa cân bằng nhất cho trải nghiệm chơi game 2K Ray Tracing mượt mà. 7168 nhân CUDA và 12GB bộ nhớ GDDR6X băng thông cao.', '{"gpu": "NVIDIA GeForce RTX 4070 SUPER", "cuda": "7168 Cores", "vram": "12GB GDDR6X 192-bit", "boost_clock": "2640 MHz", "power_req": "Nguồn đề xuất 650W, đầu cấp 16-pin"}', 1, 1, 'active'),
(14, 5, 9, 'RAM-CORSAIR-D5-32G', 'RAM Corsair Dominator Titanium RGB 32GB (2x16GB) DDR5 6000MHz Black', 'corsair-dominator-titanium-rgb-32gb-ddr5', 4790000.00, 4290000.00, 35, 'https://images.unsplash.com/photo-1562976540-1502c2145186?auto=format&fit=crop&w=800&q=80', 'Thanh RAM DDR5 phân khúc cao cấp nhất với nắp trên tháo rời và đèn LED RGB Capellix rực rỡ.', 'Vỏ nhôm rèn chính xác, chip nhớ phân loại thủ công cho khả năng ép xung XMP 3.0 cực kỳ ổn định trên nền tảng Intel và AMD.', '{"type": "DDR5", "capacity": "32GB (2 x 16GB)", "bus_speed": "6000 MT/s", "timing": "CL30-36-36-76", "voltage": "1.40V", "support": "Intel XMP 3.0 & AMD EXPO"}', 0, 0, 'active'),
(15, 5, 10, 'SSD-KC3000-1TB', 'Ổ cứng SSD Kingston KC3000 1TB M.2 PCIe Gen 4x4 NVMe (7000MB/s)', 'kingston-kc3000-1tb-pcie-gen-4x4-nvme', 2590000.00, 2290000.00, 50, 'https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?auto=format&fit=crop&w=800&q=80', 'Tốc độ đọc ghi kinh ngạc lên đến 7,000MB/s, tản nhiệt nhôm graphene mỏng nhẹ cho PC và PS5.', 'Sử dụng bộ điều khiển Phison E18 mới nhất và chip nhớ 3D TLC NAND cao cấp. Tối ưu thời gian khởi động hệ điều hành và load game siêu nhanh.', '{"interface": "PCIe 4.0 NVMe M.2 2280", "capacity": "1TB (1024GB)", "read_speed": "Lên tới 7,000 MB/s", "write_speed": "Lên tới 6,000 MB/s", "endurance": "800 TBW"}', 0, 0, 'active'),

-- 6. Tai nghe & Âm thanh
(16, 6, 6, 'SONY-WH1000XM5', 'Tai nghe chụp tai Sony WH-1000XM5 Chống Ồn Đỉnh Cao - Đen', 'sony-wh-1000xm5-chong-on-dinh-cao', 8490000.00, 7290000.00, 22, 'https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=800&q=80', '2 bộ xử lý âm thanh, 8 micro khử ồn tự động tối ưu hóa và chất lượng đàm thoại trong trẻo hàng đầu.', 'Chiếc tai nghe over-ear chống ồn tốt nhất hiện nay. Màng loa 30mm thiết kế đặc biệt mang lại âm thanh độ phân giải cao Hi-Res Audio, thời lượng pin 30 giờ liên tục.', '{"driver": "30mm màng loa sợi carbon", "anc": "Bộ xử lý tích hợp V1 + QN1 với 8 micro", "bluetooth": "5.2, Codec LDAC, AAC, SBC", "battery": "30 giờ (bật ANC), Sạc nhanh 3 phút nghe 3 giờ", "weight": "250g"}', 1, 0, 'active'),
(17, 6, 1, 'AIRPODS-PRO-2-USBC', 'Tai nghe Apple AirPods Pro 2 MagSafe (USB-C) Chính Hãng', 'apple-airpods-pro-2-magsafe-usb-c', 6190000.00, 5390000.00, 60, 'https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?auto=format&fit=crop&w=800&q=80', 'Chip Apple H2, tính năng Âm Thanh Thích Ứng (Adaptive Audio) và khả năng chống ồn gấp đôi.', 'Hộp sạc nâng cấp cổng USB-C bền bỉ chuẩn mới, loa tích hợp trên hộp sạc hỗ trợ tính năng Tìm Chính Xác (Precision Finding). Kháng nước và mồ hôi chuẩn IP54.', '{"chip": "Apple H2 trong tai nghe, Apple U1 trong hộp sạc", "audio": "Âm thanh không gian cá nhân hóa Spatial Audio", "battery": "6 giờ nghe liên tục (30 giờ kèm hộp sạc)", "connectivity": "Bluetooth 5.3, Cổng sạc USB-C và MagSafe"}', 1, 1, 'active'),
(18, 6, 6, 'SONY-SRS-XB100', 'Loa Bluetooth Sony SRS-XB100 Siêu Nhỏ Gọn Kháng Nước IP67', 'sony-srs-xb100-loa-bluetooth-nho-gon', 1290000.00, 1090000.00, 40, 'https://images.unsplash.com/photo-1545454675-3531b543be5d?auto=format&fit=crop&w=800&q=80', 'Âm trầm Extra Bass mạnh mẽ trong thân hình nhỏ gọn, dây đeo tiện lợi cho các chuyến dã ngoại.', 'Trang bị bộ xử lý khuếch tán âm thanh Sound Diffusion Processor lan tỏa âm nhạc khắp không gian. Chống bụi chống nước IP67 và pin bền bỉ đến 16 tiếng.', '{"power": "Công suất 5W kèm màng rung thụ động Passive Radiator", "protection": "Chuẩn chống nước và bụi IP67", "battery": "Lên tới 16 giờ, Sạc qua cổng USB-C", "mic": "Tích hợp micro chống vọng cho cuộc gọi thoại"}', 0, 0, 'active'),

-- 7. Bàn phím & Phụ kiện Gaming
(19, 7, 7, 'LOGI-G-PRO-X-SUPERLIGHT-2', 'Chuột Gaming Không Dây Logitech G Pro X Superlight 2 Trắng', 'logitech-g-pro-x-superlight-2', 3690000.00, 3190000.00, 28, 'https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?auto=format&fit=crop&w=800&q=80', 'Trọng lượng siêu nhẹ 60g, switch lai quang-cơ LIGHTFORCE và cảm biến HERO 2 độ phân giải 32,000 DPI.', 'Chuột thi đấu eSports đỉnh cao được các tuyển thủ chuyên nghiệp tin cậy hàng đầu. Tần số phản hồi không dây LIGHTSPEED 4000Hz (0.25ms) cực nhạy.', '{"sensor": "HERO 2 (100 - 32,000 DPI)", "switches": "Quang học lai cơ học LIGHTFORCE", "weight": "60 gram", "polling_rate": "Lên đến 4000Hz", "battery": "Lên đến 95 giờ sử dụng"}', 1, 0, 'active'),
(20, 7, 2, 'ROG-AZOTH-OLED', 'Bàn phím cơ ASUS ROG Azoth 75% Wireless Switch ROG NX Snow', 'ban-phim-co-asus-rog-azoth-75-wireless', 6490000.00, 5890000.00, 15, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', 'Màn hình OLED 2 inch hiển thị thông số, cấu trúc đệm Gasket mount 3 lớp tiêu âm và tính năng Hot-swap.', 'Bàn phím cơ custom lắp ráp sẵn cao cấp nhất thị trường. Kết nối 3 chế độ (Bluetooth, 2.4GHz SpeedNova, Type-C). Tặng kèm bộ dụng cụ lube switch cao cấp.', '{"layout": "75% (81 phím)", "switches": "ROG NX Snow Linear bôi trơn sẵn từ nhà máy", "mount": "Gasket Mount với 3 lớp đệm Poron/Silicone", "display": "OLED 2 inch kèm núm xoay điều khiển 3 hướng", "battery": "Hơn 2000 giờ sử dụng không dây"}', 1, 1, 'active'),
(21, 7, 7, 'LOGI-MX-MASTER-3S', 'Chuột Không Dây Logitech MX Master 3S Chống Ồn Quiet Clicks', 'chuot-logitech-mx-master-3s-quiet-clicks', 2490000.00, 2190000.00, 35, 'https://images.unsplash.com/photo-1629429408209-1f912961dbd8?auto=format&fit=crop&w=800&q=80', 'Chuẩn mực chuột công thái học cho lập trình viên và thiết kế đồ họa với cuộn từ tính MagSpeed 1000 dòng/giây.', 'Cảm biến quang học 8000 DPI hoạt động trên mọi bề mặt kể cả mặt kính trong suốt. Công nghệ click êm ái giảm 90% tiếng ồn, kết nối 3 thiết bị cùng lúc.', '{"sensor": "Darkfield 8000 DPI lướt trên mặt kính", "scroll": "Bánh lăn điện từ MagSpeed thông minh", "battery": "Sạc đầy dùng 70 ngày, Sạc 1 phút dùng 3 giờ", "features": "Logi Options+, Easy-Switch 3 thiết bị"}', 0, 0, 'active'),

-- 8. Phụ kiện điện thoại
(22, 8, 1, 'APPLE-20W-ADAPTER', 'Củ Sạc Nhanh Apple 20W Type-C Chính Hãng', 'cu-sac-nhanh-apple-20w-type-c', 550000.00, 490000.00, 120, 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?auto=format&fit=crop&w=800&q=80', 'Củ sạc chính hãng Apple chuẩn Power Delivery tối ưu hóa tốc độ sạc cho iPhone và iPad.', 'Thiết kế chân cắm tròn chuẩn Việt Nam, bảo vệ ngắn mạch và kiểm soát nhiệt độ an toàn tuyệt đối cho pin thiết bị của bạn.', '{"power": "20W Power Delivery (PD)", "port": "1x USB-C", "compatibility": "iPhone 8 đến iPhone 16 Pro Max, iPad Pro/Air", "safety": "Chứng chỉ an toàn chuẩn Apple"}', 0, 0, 'active'),
(23, 8, 5, 'SAMS-POWERBANK-20000', 'Pin Sạc Dự Phòng Samsung 20.000mAh Sạc Nhanh 45W Siêu Bền', 'pin-sac-du-phong-samsung-20000mah-45w', 1490000.00, 1250000.00, 45, 'https://images.unsplash.com/photo-1609592424368-24d1a03f56eb?auto=format&fit=crop&w=800&q=80', 'Dung lượng khủng sạc được cả laptop và điện thoại với công suất tối đa 45W Power Delivery.', 'Vỏ ngoài chế tác từ vật liệu tái chế thân thiện với môi trường. Hỗ trợ sạc nhanh đồng thời 3 thiết bị qua 3 cổng Type-C hiện đại.', '{"capacity": "20,000 mAh (74 Wh)", "output": "Tối đa 45W PD 3.0 PPS", "ports": "3 cổng USB Type-C 2 chiều", "safety": "Bảo vệ quá dòng, quá nhiệt, quá tải"}', 0, 0, 'active'),

-- 9. Thiết bị mạng & Khác
(24, 9, 11, 'TPLINK-ARCHER-AX73', 'Router Wi-Fi 6 Băng Tần Kép TP-Link Archer AX73 AX5400', 'router-wifi-6-tp-link-archer-ax73-ax5400', 2590000.00, 2190000.00, 25, 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?auto=format&fit=crop&w=800&q=80', 'Tốc độ Wi-Fi 6 siêu tốc 5400 Mbps với 6 ăng-ten ngoài độ lợi cao và công nghệ OneMesh phủ sóng toàn diện.', 'Trang bị CPU 3 nhân 1.5GHz xử lý đồng thời hàng chục thiết bị xem video 4K/8K và chơi game không gián đoạn. Bảo mật HomeShield nâng cao chống tấn công mạng.', '{"standards": "Wi-Fi 6 (802.11ax/ac/n/a/b/g)", "speed": "4804 Mbps (5 GHz) + 574 Mbps (2.4 GHz)", "antennas": "6 ăng-ten hiệu suất cao kèm Beamforming", "ports": "1x Gigabit WAN, 4x Gigabit LAN, 1x USB 3.0"}', 0, 0, 'active'),
(25, 9, 11, 'DECO-X50-3PACK', 'Hệ Thống Wi-Fi Mesh TP-Link Deco X50 AX3000 (Bộ 3 Thiết Bị)', 'he-thong-wifi-mesh-tp-link-deco-x50-ax3000-3pack', 4990000.00, 4390000.00, 15, 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?auto=format&fit=crop&w=800&q=80', 'Phủ sóng Wi-Fi 6 xuyên tường toàn bộ ngôi nhà đến 600m2, chuyển vùng mượt mà không rớt mạng.', 'Hệ thống Deco thông minh dùng thuật toán AI để tự động tối ưu hóa đường truyền mạng. Kết nối đồng thời hơn 150 thiết bị trong nhà thông minh.', '{"speed": "AX3000 (2402 Mbps trên 5GHz + 574 Mbps trên 2.4GHz)", "coverage": "Lên tới 600 m2 (bộ 3 pack)", "ports": "3 cổng Gigabit trên mỗi thiết bị Deco", "roaming": "Chuyển vùng liền mạch chuẩn 802.11k/v/r"}', 1, 0, 'active'),

-- Thêm sản phẩm bổ sung để đạt hơn 30 sản phẩm công nghệ
(26, 1, 5, 'SAMS-A55-5G', 'Samsung Galaxy A55 5G 8GB/128GB Xanh Iceblue', 'samsung-galaxy-a55-5g-128gb', 9990000.00, 8990000.00, 30, 'https://images.unsplash.com/photo-1580910051074-3eb694886505?auto=format&fit=crop&w=800&q=80', 'Khung viền kim loại cao cấp, màn hình Super AMOLED 120Hz và khả năng chống nước IP67 bền bỉ.', 'Chiếc điện thoại tầm trung quốc dân với chip Exynos 1480 có GPU đồ họa AMD RDNA thế hệ mới.', '{"display": "6.6 inch Super AMOLED 120Hz", "cpu": "Exynos 1480 8 nhân", "ram": "8GB", "storage": "128GB", "battery": "5000 mAh"}', 0, 0, 'active'),
(27, 2, 2, 'ASUS-ZENBOOK-14', 'ASUS Zenbook 14 OLED UX3405 Core Ultra 5 / 16GB / 512GB', 'asus-zenbook-14-oled-ux3405', 25990000.00, 23990000.00, 20, 'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=800&q=80', 'Tuyệt phẩm ultrabook siêu mỏng 1.2kg, màn hình Lumina OLED 3K 120Hz chuẩn màu điện ảnh.', 'Đạt chuẩn quân đội MIL-STD 810H, bàn phím ErgoSense êm ái và pin bền bỉ suốt ngày dài.', '{"display": "14 inch 3K OLED 120Hz 100% DCI-P3", "cpu": "Intel Core Ultra 5 125H", "ram": "16GB LPDDR5X", "storage": "512GB SSD", "weight": "1.2 kg"}', 0, 1, 'active'),
(28, 4, 5, 'SAMS-ODYSSEY-G7', 'Màn hình Cong Gaming Samsung Odyssey G7 32 inch 2K 240Hz 1000R', 'samsung-odyssey-g7-32-inch-2k-240hz', 14990000.00, 12990000.00, 14, 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=800&q=80', 'Độ cong hoàn hảo 1000R tương thích trường nhìn mắt người, tần số quét 240Hz và chấm lượng tử QLED.', 'Trải nghiệm đắm chìm trong các tựa game bắn súng và đua xe đỉnh cao với thời gian đáp ứng 1ms.', '{"size": "32 inch cong 1000R", "resolution": "2K (2560x1440)", "refresh_rate": "240Hz", "panel": "VA QLED Quantum Dot"}', 0, 0, 'active'),
(29, 5, 12, 'MAIN-MSI-Z790-TOMAHAWK', 'Bo Mạch Chủ MSI MAG Z790 TOMAHAWK WIFI DDR5', 'mainboard-msi-mag-z790-tomahawk-wifi', 7990000.00, 7190000.00, 22, 'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=800&q=80', 'Thiết kế nguồn 16+1+1 Duet Rail 90A SPS cực kỳ mạnh mẽ, tản nhiệt Extended Heatsink đồ sộ.', 'Bo mạch chủ chuẩn ATX tối ưu cho các bộ vi xử lý Intel Core thế hệ 14 mới nhất.', '{"socket": "LGA 1700", "chipset": "Intel Z790", "ram_slots": "4x DDR5 up to 7200+ MHz (OC)", "storage": "4x M.2 PCIe 4.0 NVMe", "wireless": "Wi-Fi 6E & Bluetooth 5.3"}', 0, 0, 'active'),
(30, 6, 1, 'AIRPODS-MAX-USBC', 'Tai nghe chụp tai Apple AirPods Max (USB-C) - Midnight', 'apple-airpods-max-usb-c-midnight', 13990000.00, 12890000.00, 10, 'https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=800&q=80', 'Thiết kế vòm lưới thoáng khí độc đáo, âm thanh chân thực với chip H1 trên mỗi bên củ tai.', 'Vỏ chụp tai bằng nhôm anod hóa sang trọng, chế độ Xuyên Âm tự nhiên nhất thế giới tai nghe.', '{"driver": "40mm Dynamic do Apple thiết kế", "anc": "Chống ồn chủ động chuyên nghiệp", "battery": "20 giờ nghe nhạc với ANC", "connector": "USB-C"}', 1, 1, 'active'),
(31, 7, 9, 'CORSAIR-K70-MAX', 'Bàn phím cơ Corsair K70 MAX RGB Magnetic Switch MGX', 'ban-phim-corsair-k70-max-rgb-mgx', 5690000.00, 4990000.00, 18, 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=800&q=80', 'Switch từ tính CORSAIR MGX cho phép tùy chỉnh điểm kích hoạt siêu nhạy từ 0.4mm đến 3.6mm.', 'Tích hợp tính năng Rapid Trigger giúp game thủ phản xạ nhanh như chớp trong game FPS.', '{"switch": "Magnetic MGX từ tính", "polling": "8000Hz công nghệ AXON", "keycaps": "Double-shot PBT bền bỉ", "wrist_rest": "Đệm kê tay từ tính mút hoạt tính êm ái"}', 0, 0, 'active'),
(32, 8, 1, 'MAGSAFE-CHARGER-1M', 'Đế Sạc Không Dây Apple MagSafe Charger 1m Chính Hãng', 'de-sac-khong-day-apple-magsafe-charger-1m', 1190000.00, 990000.00, 60, 'https://images.unsplash.com/photo-1622445262464-84b1456045b6?auto=format&fit=crop&w=800&q=80', 'Nam châm căn chỉnh chuẩn xác gắn chặt vào mặt lưng iPhone 12 đến 16, công suất sạc lên đến 25W.', 'Tương thích tiêu chuẩn sạc Qi2 mới nhất, hỗ trợ sạc cả tai nghe AirPods Pro.', '{"type": "Sạc không dây từ tính", "power": "Lên tới 25W với củ sạc 30W", "cable": "Cáp bọc dù 1m chống đứt"}', 0, 0, 'active');

