INSERT INTO `reviews` (`id`, `product_id`, `user_id`, `rating`, `comment`, `is_approved`, `created_at`) VALUES
(1, 1, 2, 5, 'Máy đẹp xuất sắc, viền màn hình siêu mỏng, nút camera control dùng rất thích. Đóng gói cẩn thận và giao nhanh.', 1, '2026-10-15 16:00:00'),
(2, 4, 3, 5, 'M3 Pro chạy Docker và Xcode mượt mà, máy chạy mát rượi cả ngày, pin dùng được 14 tiếng liên tục.', 1, '2026-10-16 10:30:00'),
(3, 10, 4, 5, 'Màn hình Dell UltraSharp màu sắc chuẩn xác, tấm nền IPS Black tương phản sâu rất đáng tiền cho dân thiết kế.', 1, '2026-10-15 11:00:00'),
(4, 16, 2, 5, 'Chống ồn của Sony XM5 phải nói là đỉnh nhất hiện nay, đeo rất êm không bị bí tai.', 1, '2026-10-16 17:45:00');
